#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
# remembers only the site's public address between runs (git ignores .env.*). Secrets go
# straight from each site into Render: never into .env, which runs your local development
ENV_FILE=".env.deploy"
REPO="Sriharsha-dev369/PairSpace"

banner "Deploy PairSpace: Neon, Sentry, Render, GitHub"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "You'll create three free accounts (Neon, Sentry, Render) and one GitHub OAuth App."
say "Render's always-on plan costs about \$7 a month: have a payment card ready."
say "Secrets you copy go straight into Render's dashboard; this script never stores them."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "GitHub CLI is signed in: the last stages can set the smoke test's address and run it."
else
  warn "The GitHub CLI isn't signed in. Stages 5 and 7 will tell you what to do by hand"
  warn "(or run 'gh auth login' now in another terminal, then continue)."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: the database"
open_url "https://console.neon.tech/signup"
step "Sign up (Continue with GitHub is quickest)."
step "Create a project: name it pairspace, region AWS Asia Pacific (Singapore)."
note "Singapore: next to the Render server (also Singapore), so every save is a short trip."
step "On the project's dashboard, click Connect."
step "Turn OFF connection pooling (PairSpace keeps its own pool of connections)."
step "Copy the connection string: postgresql://…neon.tech/neondb?sslmode=require"
note "Keep this tab open: you'll paste the string into Render in stage 4."
pause "Copied it? Press Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Sentry: error reports"
open_url "https://sentry.io/signup/"
step "Sign up, and create an organization when asked (any name)."
step "Create a project: platform Node.js, name pairspace-server. Copy its DSN"
note "  (https://…@….ingest.sentry.io/…). It's on the setup page, and later under"
note "  Settings → Projects → pairspace-server → Client Keys (DSN)."
step "Create a second project: platform React, name pairspace-web. Copy its DSN too."
note "Keep both DSNs at hand for stage 4. Sentry then emails you when PairSpace has an error."
pause "Got both DSNs? Press Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Render: deploy"
open_url "https://dashboard.render.com/register"
step "Sign up with GitHub, and add a payment card (Account settings → Billing)."
step "Click New → Blueprint, connect GitHub, and pick the $REPO repository."
note "Render reads render.yaml from the repo: one web service called pairspace, in Singapore."
step "Render asks for the values marked secret. Paste:"
note "  DATABASE_URL     ← Neon's connection string (stage 2)"
note "  SENTRY_DSN       ← pairspace-server's DSN"
note "  VITE_SENTRY_DSN  ← pairspace-web's DSN"
note "  GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET: leave empty for now (stage 6)"
step "Click Apply (or Deploy Blueprint). The first build takes about 5 minutes."
step "Open the pairspace service → Logs, and wait for: Serving the web app from ../web/dist"
warn "If it says \"PairSpace can't start. Set these:\", it lists what's missing: fix those"
warn "under the service's Environment tab, then Manual Deploy → Deploy latest commit."
pause "Is it live (the service page says Live)? Press Enter"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The site's address"
say "It's at the top of the pairspace service page, like https://pairspace-xxxx.onrender.com"
while true; do
  ask PRODUCTION_URL "Paste the address:"
  PRODUCTION_URL="${PRODUCTION_URL%/}"
  [[ "$PRODUCTION_URL" =~ ^https://[^/]+$ ]] && break
  warn "That should look like https://pairspace-xxxx.onrender.com (no path after it)."
done
write_env PRODUCTION_URL "$PRODUCTION_URL"
set_var PRODUCTION_URL "$PRODUCTION_URL" # the daily smoke test checks this site
if curl -fsS "$PRODUCTION_URL/api/health" >/dev/null 2>&1; then
  printf '  %s✓ the server answers, and so does its database%s\n' "$GREEN" "$RESET"
else
  warn "$PRODUCTION_URL/api/health doesn't answer yet. Check Render's Logs, then continue."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub sign-in on the site"
say "A GitHub OAuth App sends people back to one address, so the site needs its own app"
say "(keep the one in your local .env for development)."
open_url "https://github.com/settings/applications/new"
step "Application name: PairSpace"
step "Homepage URL: $PRODUCTION_URL"
step "Authorization callback URL: $PRODUCTION_URL/api/auth/callback/github"
step "Click Register application, copy the Client ID, then Generate a new client secret and copy it."
step "In Render: the pairspace service → Environment → set GITHUB_CLIENT_ID and"
note "  GITHUB_CLIENT_SECRET to those two values → Save changes (Render redeploys: ~5 minutes)."
pause "Saved, and the service is Live again? Press Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Smoke test"
say "Checks the site end to end: it loads, the server and database are up, and a room syncs"
say "live between two browsers (this signs up a throwaway member on your site)."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
  && confirm "Run it now on GitHub Actions?"; then
  gh workflow run smoke.yml --repo "$REPO" -f url="$PRODUCTION_URL" -f deep=true
  note "Started. Following it (about 2 minutes):"
  sleep 5
  run_id=$(gh run list --repo "$REPO" --workflow smoke.yml --limit 1 --json databaseId -q '.[0].databaseId')
  if gh run watch "$run_id" --repo "$REPO" --exit-status; then
    printf '  %s✓ smoke test passed: PairSpace is live at %s%s\n' "$GREEN" "$PRODUCTION_URL" "$RESET"
  else
    SKIPPED+=("smoke test failed: gh run view $run_id --repo $REPO --log-failed")
  fi
else
  say "Run it from the repo instead:"
  note "  BASE_URL=$PRODUCTION_URL npx playwright test e2e/smoke.spec.ts --project chromium"
  SKIPPED+=("the smoke test (command above)")
fi
pause

finish
}

run_wizard "$@"; exit
